import{_ as o,c as a,o as t,aj as r}from"./chunks/framework.e3UxQEvm.js";const p=JSON.parse('{"title":"Privacy Notice","description":"","frontmatter":{},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md"}'),i={name:"privacy.md"};function s(n,e,d,c,l,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="privacy-notice" tabindex="-1">Privacy Notice <a class="header-anchor" href="#privacy-notice" aria-label="Permalink to “Privacy Notice”">​</a></h1><p>Your SolidCouch data live on a <a href="#solid-pod">Solid Pod</a> of your choice. We don&#39;t control them. We try to store as little data about you as possible. Thanks to Solid protocol, it is quite little.</p><h2 id="this-is-an-experimental-service" tabindex="-1">This is an experimental service <a class="header-anchor" href="#this-is-an-experimental-service" aria-label="Permalink to “This is an experimental service”">​</a></h2><p>You&#39;re using this service at your own risk. SolidCouch developers or community infrastructure provider can not bear any responsibility (unless they state otherwise elsewhere).</p><p>Please keep in mind that SolidCouch is an experimental open-source software built by volunteers. The software or the community you&#39;re joining may change or get abandoned. Even if that happens, your data (profile, contacts, messages, ...) will stay on your Solid Pod, and you may use them again.</p><p>If you use a Solid Pod provider to host your Solid Pod, they probably have access to all your data, and they may discontinue their service. This is where your data are at risk. This is out of our control. Please choose accordingly or host your Solid Pod yourself.</p><p>Meeting strangers via hospitality exchange comes with a risk. Most people tend to be good, hospitable and kind, but predators exist. The SolidCouch developers intend to implement social reputation system in the future. Please read Terms of Service of the community you&#39;re joining. Unless we say otherwise, we probably can not offer you any support beyond the matching service itself.</p><p>Please trust your gut, stay safe, and have a backup plan. Don&#39;t hesitate to leave an uncomfortable situation and contact local law enforcement if you find yourself in any danger.</p><h2 id="who-is-we" tabindex="-1">Who is &quot;we?&quot; <a class="header-anchor" href="#who-is-we" aria-label="Permalink to “Who is &quot;we?&quot;”">​</a></h2><p>&quot;We&quot; are the person, people, or organization who host the infrastructure for the community you&#39;re joining. Please find out more on the community page.</p><p>SolidCouch developers provide the software. They&#39;re not responsible for the community you&#39;re joining.</p><h2 id="how-we-handle-your-data" tabindex="-1">How we handle your data <a class="header-anchor" href="#how-we-handle-your-data" aria-label="Permalink to “How we handle your data”">​</a></h2><p>We only handle and store minimum necessary data for functioning of the community.</p><p>(lawful basis: contractual necessity)</p><h3 id="your-profile" tabindex="-1">Your profile <a class="header-anchor" href="#your-profile" aria-label="Permalink to “Your profile”">​</a></h3><p>We store your <a href="#webid">WebID</a> (link to your profile) in a publicly accessible list of community members. This is currently a technical necessity so members can find and share data with each other. We don&#39;t store any data from your profile.</p><p>To remove your WebID from the list, you will be able to leave the community. In the meantime, please contact the community administrators.</p><h3 id="your-accommodation-offers" tabindex="-1">Your accommodation offers <a class="header-anchor" href="#your-accommodation-offers" aria-label="Permalink to “Your accommodation offers”">​</a></h3><p>If you offer accommodation to other members, we keep a location (geohash) and link to the offer in <a href="https://github.com/solidcouch/geoindex" target="_blank" rel="noreferrer">geoindex service</a>. This service allows other members to find your offers on the map. We don&#39;t keep any other data about your accommodation offers.</p><p>To stay up to date, the geoindex service regularly fetches your profile to discover your accommodations. It doesn&#39;t store any of these data.</p><p>To remove the URI and location of your accommodation offer from the service, you can delete it via the app.</p><h3 id="your-email-address-and-email-notifications" tabindex="-1">Your email address and email notifications <a class="header-anchor" href="#your-email-address-and-email-notifications" aria-label="Permalink to “Your email address and email notifications”">​</a></h3><p>Your email address is stored on your Solid Pod. <a href="https://github.com/solidcouch/solid-email-notifications-direct" target="_blank" rel="noreferrer">Email notification service</a> accesses this email when it needs to send you an email notification. The service does not keep this email address stored anywhere.</p><p>The notification service also needs to process content of the notification you send or receive. This may include your name, message with other person, contact request, experience, and other sensitive information. The notification service doesn&#39;t store any of these data. It sends the notification and forgets about it.</p><p>The notification service may use a third party SMTP service to send email notifications to/from you (for example <a href="https://sendgrid.com" target="_blank" rel="noreferrer">SendGrid</a>, <a href="https://support.sparkpost.com" target="_blank" rel="noreferrer">SparkPost</a>, <a href="https://aws.amazon.com/ses/" target="_blank" rel="noreferrer">AWS SES</a>, …). Your email address and message content are shared with this third party. Please check with your community operator which SMTP service they use.</p><p>You can stop participating in this by leaving the community. To be sure, also change access to your email address on your Solid Pod.</p><p>In the future, we may provide option to host your own email notification service.</p><h3 id="other-data" tabindex="-1">Other data <a class="header-anchor" href="#other-data" aria-label="Permalink to “Other data”">​</a></h3><p>We don&#39;t store any other data about you.</p><p>We are not able to read your messages.</p><p>Other members can read information about you directly from you Solid Pod via the community app: Your profile, contacts, accommodation offers, etc.</p><p>Please keep in mind that if you use a Solid Pod provider, they probably have a direct access to your data on their servers. Please read their privacy information and choose accordingly, or host your Pod yourself.</p><h2 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to “Glossary”">​</a></h2><h3 id="solid-pod" tabindex="-1">Solid Pod <a class="header-anchor" href="#solid-pod" aria-label="Permalink to “Solid Pod”">​</a></h3><p>Your identity and data storage on the internet. You can host the pod yourself, or use a provider. If you choose a provider, it can probably access your data, so choose accordingly.</p><h3 id="webid" tabindex="-1">WebID <a class="header-anchor" href="#webid" aria-label="Permalink to “WebID”">​</a></h3><p>WebID is a URI that represents you and links to a document about you (Solid WebID Profile). It often ends with <code>/profile/card#me</code>, but not always.</p>',37)])])}const m=o(i,[["render",s]]);export{p as __pageData,m as default};
